(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const SITE_ORIGIN='https://anillos-draco-colombia.aalvarocarrero.chatgpt.site';const PHONE='573215587953';const PRIVATE_PREVIEW=true;let products=[],cart=[],filter='Todos',visibleLimit=24,ready=false;const returnFocus=new WeakMap();let sharedOrder=[];
const money=value=>'$'+value.toLocaleString('es-CO')+' COP';const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();
try{const saved=localStorage.getItem('draco-cart-v2');const stored=JSON.parse(saved||localStorage.getItem('draco-selection-v1')||'[]');cart=Array.isArray(stored)?stored.map(x=>typeof x==='string'?{id:x,quantity:1}:x):[]}catch{cart=[]}
function sanitize(items){const rows=new Map();if(!Array.isArray(items))return[];for(const row of items){if(!row||typeof row.id!=='string'||!products.some(p=>p.id===row.id))continue;const q=Number(row.quantity);if(!Number.isInteger(q)||q<1||q>99)continue;rows.set(row.id,Math.min(99,(rows.get(row.id)||0)+q))}return[...rows].map(([id,quantity])=>({id,quantity}))}
function mergeCart(extra){const totals=new Map();for(const row of [...cart,...extra]){const next=(totals.get(row.id)||0)+row.quantity;if(next>99)throw Error('Una referencia supera 99 unidades. Ajusta la cantidad o consulta un pedido mayor por WhatsApp.');totals.set(row.id,next)}return sanitize([...cart,...extra])}
function save(){try{localStorage.setItem('draco-cart-v2',JSON.stringify(cart))}catch{}const units=cart.reduce((s,x)=>s+x.quantity,0);$('#count').textContent=units;const floating=$('#floating-cart');if(floating){floating.hidden=units===0;floating.setAttribute('aria-label','Abrir carrito con '+units+' anillos');$('#floating-cart-count').textContent=units}resetPhotos()}
function toast(text){const e=$('#toast');e.textContent=text;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2800)}
function element(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el}
function openDialog(d){if(d.open)return;returnFocus.set(d,document.activeElement);d.showModal()}
function setMenu(open){$('#nav').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')}
$('#menu').onclick=()=>setMenu(!$('#nav').classList.contains('open'));$('#nav').addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#nav').classList.contains('open')){const inside=$('#nav').contains(document.activeElement);setMenu(false);if(inside)$('#menu').focus()}});
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>{d.addEventListener('close',()=>{const t=returnFocus.get(d);if(t?.isConnected&&!t.closest('dialog:not([open])'))t.focus()});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
function setResults(reset=true){if(reset)visibleLimit=24;const query=normalize($('#search')?.value||'');const cards=$$('.card'),matching=[];for(const c of cards){if((filter==='Todos'||c.dataset.category===filter)&&normalize(c.dataset.name).includes(query))matching.push(c);c.hidden=true}matching.slice(0,visibleLimit).forEach(c=>c.hidden=false);$('.empty')?.toggleAttribute('hidden',matching.length>0);if($('#results-count'))$('#results-count').textContent=matching.length+' diseños'+(query?' para «'+$('#search').value.trim()+'»':'');if($('#more')){$('#more').hidden=matching.length<=visibleLimit;$('#more').textContent='Mostrar más ('+Math.max(0,matching.length-visibleLimit)+')'}}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));setResults()});$('#search')?.addEventListener('input',()=>setResults());$('#more')?.addEventListener('click',()=>{const before=new Set($$('.card').filter(c=>!c.hidden));visibleLimit+=24;setResults(false);$$('.card').find(c=>!c.hidden&&!before.has(c))?.querySelector('a')?.focus()});if($('#search'))setResults();
function productLink(p){return SITE_ORIGIN+p.url}
function orderLink(items){const packed=items.map(x=>products.find(p=>p.id===x.id).share_id+'.'+x.quantity).join('_');return SITE_ORIGIN+'/pedido/?p='+encodeURIComponent(packed)}
function compose(items,includeCustomer=false){const total=items.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.quantity,0),units=items.reduce((s,x)=>s+x.quantity,0);const link=orderLink(items);const lines=items.map((x,i)=>{const p=products.find(p=>p.id===x.id);return(i+1)+'. '+p.name+'\nSKU: '+p.sku+'\nCantidad: '+x.quantity+' · '+money(p.price)+' c/u\nSubtotal: '+money(p.price*x.quantity)+'\nFicha: '+productLink(p)});const customer=includeCustomer?customerText():'';const ending=customer+(includeCustomer&&receiptReference?'\nReferencia del recibo: '+receiptReference:'')+'\n\nTOTAL: '+money(total)+'\nEnvío incluido a toda Colombia.\nPedido completo: '+link+'\nQuiero confirmar disponibilidad, plazo de entrega y acordar el pago.';const full='Hola, estoy interesado en este pedido de Anillos Draco:\n\n'+lines.join('\n\n')+ending;if(PRIVATE_PREVIEW&&encodeURIComponent(full).length>7000)return{full,compact:true,requiresCopy:true,total,units,link,href:'https://wa.me/'+PHONE};let sent=full,compact=false;if(encodeURIComponent(full).length>7000){compact=true;const names=items.map(x=>x.quantity+' × '+products.find(p=>p.id===x.id).name).join('\n');sent='Hola, quiero consultar '+units+' anillos Draco:\n'+names+ending;if(encodeURIComponent(sent).length>7000)sent='Hola, quiero consultar un pedido Draco de '+units+' anillos ('+items.length+' modelos).\nTotal: '+money(total)+'\nEnvío incluido a toda Colombia.\nDetalle completo, cantidades y enlaces de cada anillo: '+link+'\nQuiero confirmar disponibilidad y acordar el pago.'}return{full,compact,requiresCopy:false,total,units,link,href:'https://wa.me/'+PHONE+'?text='+encodeURIComponent(sent)}}
function add(id,q=1){if(!ready){toast('El catálogo está cargando. Intenta nuevamente.');return}if(!products.some(p=>p.id===id))return;const row=cart.find(x=>x.id===id);if(row){if(row.quantity>=99){toast('Para más de 99 unidades de un modelo, consúltanos por WhatsApp.');return}row.quantity=Math.min(99,row.quantity+q)}else cart.push({id,quantity:Math.min(99,q)});save();toast('Añadido al carrito')}
$$('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add));
function detail(id){const p=products.find(p=>p.id===id);if(!p){toast('El catálogo todavía está cargando.');return}const body=$('#detail-body');body.replaceChildren();const eyebrow=element('span',p.category,'eyebrow'),heading=element('h2',p.name);heading.id='detail-title';const media=element('div',undefined,'detail-media'+(p.retouched?' is-retouched'+(p.photo_alpha?' has-alpha':' opaque-photo'):''));const img=element('img');img.src=p.image;img.alt=p.name;img.className='detail-image';img.width=p.image_width;img.height=p.image_height;if(p.retouched){img.style.setProperty('--photo-scale',p.photo_scale||1);img.style.setProperty('--photo-x',(p.photo_x||0)+'%');img.style.setProperty('--photo-y',(p.photo_y||0)+'%')}media.append(img);const description=element('p',p.description),note=element('p',money(p.price)+' · Envío incluido a toda Colombia'),addButton=element('button','Añadir al carrito +','button outline');addButton.onclick=()=>{add(id);$('#detail').close()};const buy=element('a','Comprar por WhatsApp ↗','button whatsapp');buy.href=compose([{id,quantity:1}]).href;buy.target='_blank';buy.rel='noopener';buy.onclick=e=>{e.preventDefault();if(!cart.some(x=>x.id===id))add(id);$('#detail').close();renderCart();openDialog($('#selection'))};const link=element('a','Ver ficha completa ↗','textlink');link.href=p.url;const actions=element('div',undefined,'actions');actions.append(buy,addButton,link);body.append(eyebrow,heading,media,description,note,actions);openDialog($('#detail'))}
$$('[data-product]').forEach(b=>b.onclick=()=>detail(b.dataset.product));
async function copyOrder(items,textarea,includeCustomer=false){const text=compose(items,includeCustomer).full;try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);toast('Pedido copiado')}catch{textarea.hidden=false;textarea.value=text;textarea.focus();textarea.select();toast('Selecciona y copia el detalle del pedido')}}
function changeQuantity(id,quantity,focusAction){const n=Number(quantity);if(!Number.isInteger(n)||n<1||n>99){toast('Elige entre 1 y 99 unidades por modelo.');renderCart({id,action:'quantity'});return}cart.find(x=>x.id===id).quantity=n;save();renderCart({id,action:focusAction})}
function renderCart(focus=null){if($('#create-receipt'))$('#create-receipt').hidden=!cart.length||!!receiptFile;if($('#customer-form'))$('#customer-form').hidden=!cart.length;const rows=$('#selection-items');rows.replaceChildren();const inquiry=$('#inquiry'),copy=$('#copy-order');$('#copy-fallback').hidden=true;if(!cart.length){rows.append(element('p','Tu carrito está vacío. Añade los anillos que te gusten y elige las cantidades.'));inquiry.hidden=true;copy.hidden=true;if($('#prepare-photos'))$('#prepare-photos').hidden=true;$('#message-note').textContent='';if(focus)$('#selection [data-close]').focus();return}cart.forEach((x,index)=>{const p=products.find(p=>p.id===x.id);const row=element('div',undefined,'cart-line');row.dataset.id=x.id;const photo=element('img');photo.src=p.image;photo.alt=p.name;photo.className='cart-thumb';photo.width=64;photo.height=64;const content=element('div',undefined,'cart-line-content');const name=element('a',p.name);name.href=p.url;content.append(name,element('p','SKU '+p.sku+' · '+money(p.price)+' por unidad','cart-unit-price'));const qty=element('div',undefined,'quantity-control');const minus=element('button','−');minus.dataset.action='minus';minus.setAttribute('aria-label','Reducir cantidad de '+p.name);minus.disabled=x.quantity===1;minus.onclick=()=>changeQuantity(x.id,x.quantity-1,'minus');const input=element('input');input.type='number';input.min='1';input.max='99';input.step='1';input.inputMode='numeric';input.value=x.quantity;input.dataset.action='quantity';input.setAttribute('aria-label','Cantidad de '+p.name);input.onchange=()=>changeQuantity(x.id,input.value,'quantity');const plus=element('button','+');plus.dataset.action='plus';plus.setAttribute('aria-label','Aumentar cantidad de '+p.name);plus.disabled=x.quantity===99;plus.onclick=()=>changeQuantity(x.id,x.quantity+1,'plus');qty.append(minus,input,plus);content.append(qty,element('p','Subtotal: '+money(p.price*x.quantity),'cart-subtotal'));const remove=element('button','×','cart-remove');remove.dataset.action='remove';remove.setAttribute('aria-label','Quitar '+p.name);remove.onclick=()=>{cart=cart.filter(y=>y.id!==x.id);save();const next=cart[Math.min(index,cart.length-1)];renderCart(next?{id:next.id,action:'remove'}:{})};row.append(photo,content,remove);rows.append(row)});const message=compose(cart,true);rows.append(element('p',message.units+' anillos · Total: '+money(message.total),'selection-total'));inquiry.hidden=!receiptFile;inquiry.href=receiptFile?message.href:'';inquiry.textContent='2. Continuar pedido por WhatsApp';copy.hidden=!receiptFile;if($('#prepare-photos'))$('#prepare-photos').hidden=true;copy.onclick=()=>copyOrder(cart,$('#copy-fallback'),true);$('#message-note').textContent=message.requiresCopy?'Pedido largo: copia el detalle completo y pégalo en WhatsApp. Esta vista es privada; los enlaces son para pruebas hasta publicar el dominio.':message.compact?'Por el tamaño del pedido, WhatsApp incluye un enlace al detalle completo con todos los productos. También puedes copiar el listado íntegro.':'WhatsApp abrirá el pedido con cantidades, total y enlaces. Pulsa Enviar allí para que llegue a Draco.';refreshCustomerMessage();if($('#prepare-photos')&&!photoFiles.length)void prepareProductPhotos();if(focus?.id){const row=[...rows.querySelectorAll('.cart-line')].find(r=>r.dataset.id===focus.id);const target=row?.querySelector('[data-action="'+focus.action+'"]');if(target&&!target.disabled)target.focus();else row?.querySelector('[data-action="quantity"]')?.focus()}}
$('#floating-cart')?.addEventListener('click',()=>$('#bag').click());
$('#bag').onclick=()=>{if(!ready){toast('El catálogo todavía está cargando.');return}renderCart();openDialog($('#selection'))};
function parseOrder(){const packed=new URLSearchParams(location.search).get('p');if(!packed)return[];if(packed.length>5000)throw Error('Pedido demasiado largo');const rows=packed.split('_').map(part=>{const match=/^([a-f0-9]{8})\.([1-9][0-9]?)$/.exec(part);if(!match)throw Error('Formato de pedido no válido');const p=products.find(p=>p.share_id===match[1]);if(!p)throw Error('Una referencia ya no está en el catálogo');return{id:p.id,quantity:Number(match[2])}});return sanitize(rows)}
function renderSharedOrder(){const root=$('#order-list');if(!root)return;try{sharedOrder=parseOrder();root.replaceChildren();if(!sharedOrder.length){root.append(element('p','Este enlace no contiene un pedido. Explora la colección y prepara tu carrito.'));return}sharedOrder.forEach(x=>{const p=products.find(p=>p.id===x.id);const row=element('article',undefined,'shared-order-line');const img=element('img');img.src=p.image;img.alt=p.name;img.loading='lazy';img.width=100;img.height=100;const text=element('div');const name=element('a',p.name);name.href=p.url;text.append(name,element('p','Cantidad: '+x.quantity+' · '+money(p.price)+' c/u'),element('strong','Subtotal: '+money(x.quantity*p.price)));row.append(img,text);root.append(row)});const message=compose(sharedOrder);root.append(element('p','Total: '+money(message.total)+' · Envío incluido','selection-total'));$('#order-actions').hidden=false;$('#order-whatsapp').href=message.href;$('#order-whatsapp').textContent=message.requiresCopy?'Abrir WhatsApp para pegar pedido ↗':'Consultar este pedido por WhatsApp ↗';const guidance=element('p',message.requiresCopy?'Pedido largo: copia el detalle completo y pégalo en WhatsApp. Esta vista es privada; los enlaces son para pruebas hasta publicar el dominio.':'Vista privada: los enlaces del pedido son para pruebas hasta publicar el dominio definitivo.','preview-cart-note');root.append(guidance);$('#order-copy').onclick=()=>copyOrder(sharedOrder,$('#order-copy-fallback'));$('#order-add-cart').onclick=()=>{try{cart=mergeCart(sharedOrder);save();renderCart();openDialog($('#selection'));toast('Pedido añadido al carrito')}catch(e){toast(e.message)}};}catch(e){root.textContent='No pudimos abrir este pedido. Comprueba el enlace o prepara uno nuevo en la colección.'}}
$('#diameter')?.addEventListener('input',()=>{const v=Number($('#diameter').value);$('#measurement').textContent=v>=10&&v<=30?'Circunferencia aproximada: '+(v*Math.PI).toLocaleString('es-CO',{maximumFractionDigits:1})+' mm':'Introduce un diámetro entre 10 y 30 mm.'});
function registerTools(){const mc=document.modelContext;if(!mc?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(mc.registerTool({name:'stage_draco_cart',title:'Preparar carrito Draco',description:'Añade modelos y cantidades al carrito local. No envía mensajes, crea pedidos ni realiza pagos.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string',enum:products.map(p=>p.id)},quantity:{type:'integer',minimum:1,maximum:99}},required:['id','quantity'],additionalProperties:false},minItems:1,maxItems:97}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='items')||!Array.isArray(input.items)||!input.items.length||input.items.length>97||input.items.some(x=>!x||Object.keys(x).some(k=>!['id','quantity'].includes(k))||!Number.isInteger(x.quantity)||x.quantity<1||x.quantity>99||!products.some(p=>p.id===x.id)))throw Error('Artículos o cantidades no válidos');cart=mergeCart(input.items);save();renderCart();if($('#detail').open)$('#detail').close();openDialog($('#selection'));return{items:cart.map(x=>({...x})),total:compose(cart).total,currency:'COP',orderCreated:false,messageSent:false}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}
function customerText(){const form=$('#customer-form');if(!form)return'';const value=id=>$('#'+id)?.value?.trim()||'';const label=id=>{const el=$('#'+id);return el?.value?(el.selectedOptions?.[0]?.textContent||el.value):''};const parts=[['Nombre',value('customer-name')],['Teléfono',value('customer-phone')],['Departamento',label('customer-department')],['Municipio / localidad',label('customer-municipality')],['Dirección',value('customer-address')]];const present=parts.filter(x=>x[1]);return present.length?'\n\nDATOS DEL CLIENTE\n'+present.map(x=>x[0]+': '+x[1]).join('\n'):''}
function validateCustomer(){const form=$('#customer-form');if(!form)return true;const name=$('#customer-name'),phone=$('#customer-phone'),address=$('#customer-address');name.setCustomValidity(name.value.trim().length<2?'Escribe tu nombre.':'');const digits=phone.value.replace(/\D/g,'');phone.setCustomValidity(digits.length<10||digits.length>15?'Escribe un teléfono válido de 10 a 15 dígitos.':'');address.setCustomValidity(address.value.trim().length<5?'Escribe una dirección con suficiente detalle.':'');return form.reportValidity()}
function refreshCustomerMessage(){if(!ready||!cart.length)return;const m=compose(cart,true);$('#inquiry').hidden=!receiptFile;$('#inquiry').href=receiptFile?m.href:'';$('#inquiry').textContent='2. Continuar pedido por WhatsApp';$('#message-note').textContent=receiptFile?'Tu recibo incluye las fotos, los productos y tus datos. Elige WhatsApp y el contacto Draco (+57 321 558 7953), y confirma el envío.':'Paso 1: completa tus datos y crea el recibo. Cuando esté listo aparecerá el botón para continuar por WhatsApp.'}

$('#customer-form')?.addEventListener('submit',e=>e.preventDefault());$('#customer-form')?.addEventListener('input',()=>{for(const id of ['customer-name','customer-phone','customer-address'])$('#'+id)?.setCustomValidity('');resetReceipt();refreshCustomerMessage()});$('#customer-form')?.addEventListener('change',()=>{resetReceipt();refreshCustomerMessage()});
$('#inquiry')?.addEventListener('click',async e=>{if(!validateCustomer()){e.preventDefault();return}refreshCustomerMessage();if(!receiptFile){e.preventDefault();$('#receipt-status').textContent='Primero crea el recibo de tu pedido.';$('#create-receipt')?.focus();return}if(navigator.share&&navigator.canShare?.({files:[receiptFile]})){e.preventDefault();const button=$('#inquiry');if(button.getAttribute('aria-busy')==='true')return;button.setAttribute('aria-busy','true');try{await navigator.share({files:[receiptFile],title:'Pedido Anillos Draco'});$('#receipt-status').textContent='Revisa que hayas elegido Draco (+57 321 558 7953) y confirma el envío en WhatsApp.'}catch(error){$('#receipt-status').textContent=error.name==='AbortError'?'Envío cancelado. Tu recibo sigue listo; puedes continuar otra vez o descargarlo.':'Este dispositivo no pudo compartir el archivo. Descarga el recibo PDF y adjúntalo en WhatsApp.'}finally{button.removeAttribute('aria-busy')}}else{$('#receipt-status').textContent='Este navegador no comparte archivos directamente. Descarga el recibo PDF y adjúntalo en el chat de WhatsApp que se abrirá.'}});

if($('#customer-department'))fetch('/colombia-locations.json').then(r=>{if(!r.ok)throw Error('Locations');return r.json()}).then(data=>{const department=$('#customer-department'),municipality=$('#customer-municipality');department.replaceChildren(new Option('Elige el departamento',''));for(const d of data.departments)department.append(new Option(d.name,d.code));department.addEventListener('change',()=>{municipality.replaceChildren(new Option('Elige el municipio o localidad',''));const d=data.departments.find(x=>x.code===department.value);municipality.disabled=!d;if(d)for(const m of d.municipalities)municipality.append(new Option(m.name+(m.type==='municipality'?'':m.type==='island'?' · Isla':' · Área no municipalizada'),m.code));refreshCustomerMessage()});$('#location-status').textContent='32 departamentos y Bogotá D.C. · El municipio se filtra según tu selección.'}).catch(()=>{for(const [id,label]of [['customer-department','Departamento'],['customer-municipality','Municipio o localidad']]){const old=$('#'+id),input=element('input');input.id=id;input.name=old.name;input.required=true;input.maxLength=100;input.placeholder=label;old.replaceWith(input)}$('#location-status').textContent='No se pudo cargar el listado. Escribe tu departamento y municipio para continuar.'});

let receiptFile=null,receiptUrl=null,receiptGeneration=0,receiptReference="";
function resetReceipt(){if($('#inquiry')){$('#inquiry').hidden=true;$('#inquiry').href=''}receiptReference="";receiptGeneration++;receiptFile=null;if(receiptUrl){URL.revokeObjectURL(receiptUrl);receiptUrl=null}if($('#download-receipt'))$('#download-receipt').hidden=true;if($('#copy-order'))$('#copy-order').hidden=true;if($('#receipt-status'))$('#receipt-status').textContent='';if($('#create-receipt')){$('#create-receipt').disabled=false;$('#create-receipt').textContent='1. Crear recibo de pedido';$('#create-receipt').hidden=!cart.length}}
$('#create-receipt')?.addEventListener('click',async()=>{if(!cart.length||!validateCustomer())return;resetReceipt();const generation=receiptGeneration,button=$('#create-receipt');button.disabled=true;button.textContent='Creando recibo…';$('#receipt-status').textContent='Preparando el PDF en este dispositivo. No se envía ni guarda en un servidor.';try{const choice=id=>{const el=$('#'+id);return el?.selectedOptions?.[0]?.textContent||el?.value||''},customer={name:$('#customer-name').value.trim(),phone:$('#customer-phone').value.trim(),address:$('#customer-address').value.trim(),department:choice('customer-department'),municipality:choice('customer-municipality')};const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);const reference='DRC-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+bytes[0].toString(16).toUpperCase().padStart(8,'0');const result=await window.createDracoReceipt({items:cart.map(x=>({...products.find(p=>p.id===x.id),quantity:x.quantity})),customer,reference,createdAt:new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',dateStyle:'medium',timeStyle:'short'}).format(new Date())+' (Colombia)'});if(generation!==receiptGeneration)return;receiptReference=reference;refreshCustomerMessage();receiptFile=new File([result.blob],reference+'.pdf',{type:'application/pdf'});receiptUrl=URL.createObjectURL(receiptFile);const download=$('#download-receipt');download.href=receiptUrl;download.download=receiptFile.name;download.hidden=false;$('#copy-order').hidden=false;refreshCustomerMessage();$('#inquiry').focus();$('#receipt-status').textContent='Recibo listo: '+reference+'. Pulsa Continuar pedido por WhatsApp para enviar el archivo. No confirma pago ni disponibilidad.';button.disabled=false;button.textContent='Recibo creado';button.hidden=true}catch{if(generation!==receiptGeneration)return;button.disabled=false;button.textContent='Reintentar recibo PDF';$('#receipt-status').textContent='No pudimos generar el PDF. Tus datos siguen aquí. Pulsa Reintentar recibo PDF para continuar.'}});


let photoFiles=[],photoUrls=[],photoGeneration=0;
function resetPhotos(){resetReceipt();photoGeneration++;for(const url of photoUrls)URL.revokeObjectURL(url);photoUrls=[];photoFiles=[];const downloads=$('#photo-downloads');if(downloads)downloads.replaceChildren();const share=$('#share-photos');if(share)share.hidden=true;const prepare=$('#prepare-photos');if(prepare){prepare.disabled=false;prepare.textContent='Preparar fotos individuales'}if($('#photo-note'))$('#photo-note').textContent='WhatsApp no adjunta fotos desde un enlace. Prepara las imágenes para compartirlas o descargarlas y adjuntarlas al pedido.'}
function loadOrderPhoto(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('No se pudo cargar una fotografía.'));img.src=src})}
function canvasBlob(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('No se pudo preparar la imagen.')),'image/png'))}
function drawWrapped(ctx,text,x,y,maxWidth,lineHeight,maxLines=3){const words=text.split(/\s+/);let line='',lines=[];for(const word of words){const next=line?line+' '+word:word;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);lines.slice(0,maxLines).forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight));}
async function prepareProductPhotos(){if(!cart.length)return;resetPhotos();const generation=photoGeneration,items=cart.map(x=>({...x})),button=$('#prepare-photos');button.disabled=true;button.textContent='Preparando fotos…';$('#photo-note').textContent='Preparando una foto real por modelo, con nombre, cantidad y precio. No se envía nada automáticamente.';try{const files=[];for(let i=0;i<items.length;i++){const item=items[i],p=products.find(x=>x.id===item.id),img=await loadOrderPhoto(p.image);if(generation!==photoGeneration)return;const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1420;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas unavailable');ctx.fillStyle='#fff';ctx.fillRect(0,0,1200,1420);ctx.fillStyle='#101011';ctx.font='bold 36px Arial';ctx.fillText('ANILLOS DRACO',55,70);ctx.font='20px Arial';ctx.fillText('Producto '+(i+1)+' de '+items.length+' · SKU '+p.sku,55,110);const ratio=Math.min(1080/img.width,1000/img.height),w=img.width*ratio,h=img.height*ratio;ctx.drawImage(img,(1200-w)/2,150+(1000-h)/2,w,h);ctx.fillStyle='#101011';ctx.font='bold 34px Arial';drawWrapped(ctx,p.name,55,1200,1090,42,2);ctx.font='26px Arial';ctx.fillText('Cantidad: '+item.quantity+' · Subtotal: '+money(p.price*item.quantity),55,1310);ctx.font='22px Arial';ctx.fillText('Envío incluido a Colombia · Total pedido: '+money(compose(items).total),55,1360);files.push(new File([await canvasBlob(canvas)],'Draco-'+String(i+1).padStart(2,'0')+'-'+p.id+'.png',{type:'image/png'}))}if(generation!==photoGeneration)return;photoFiles=files;const area=$('#photo-downloads');files.forEach((file,i)=>{const url=URL.createObjectURL(file);photoUrls.push(url);const link=element('a','Foto '+(i+1)+' · '+products.find(p=>p.id===items[i].id).name,'photo-download');link.href=url;link.download=file.name;area.append(link)});const canShare=typeof navigator.canShare==='function'&&navigator.canShare({files});$('#share-photos').hidden=!canShare;$('#share-photos').textContent='Compartir '+files.length+' foto'+(files.length===1?'':'s')+' del pedido';$('#photo-note').textContent=canShare?'Fotos reales listas, una por modelo. Pulsa Compartir y elige WhatsApp y el contacto Draco: las imágenes se adjuntan como fotos, no como enlaces. Confirma allí el envío.':'Fotos reales listas, una por modelo. Este navegador no permite compartir todos los archivos juntos. Descárgalos y adjúntalos en WhatsApp.';button.textContent='Volver a preparar fotos';button.disabled=false}catch(e){if(generation!==photoGeneration)return;button.disabled=false;button.textContent='Reintentar fotos';button.hidden=false;$('#photo-note').textContent='No pudimos preparar todas las fotos. No se envió nada. Reintenta o consulta el pedido por WhatsApp.'}}
$('#prepare-photos')?.addEventListener('click',prepareProductPhotos);
$('#share-photos')?.addEventListener('click',async()=>{if(!photoFiles.length||!navigator.share)return;try{await navigator.share({files:photoFiles,title:'Mi pedido de Anillos Draco'});$('#photo-note').textContent='Revisa el destino y confirma el envío en la aplicación elegida. Puedes copiar el texto del pedido por separado.'}catch(e){$('#photo-note').textContent=e.name==='AbortError'?'Compartir cancelado. Tus imágenes siguen listas para descargar.':'No se pudo abrir el envío de fotos. Descárgalas y adjúntalas manualmente en WhatsApp.'}});

fetch('/catalog.json').then(r=>{if(!r.ok)throw Error('Catalog fetch');return r.json()}).then(data=>{if(!Array.isArray(data))throw Error('Invalid catalog');products=data;cart=sanitize(cart);ready=true;save();$$('a.card-whatsapp,.product-copy>a.whatsapp').forEach(a=>{const card=a.closest('.card');const id=card?.querySelector('[data-add]')?.dataset.add||$('.product-copy [data-add]')?.dataset.add;if(id&&products.some(p=>p.id===id)){a.href=compose([{id,quantity:1}]).href;a.onclick=e=>{e.preventDefault();if(!cart.some(x=>x.id===id))add(id);renderCart();openDialog($('#selection'))}}});renderSharedOrder();registerTools()}).catch(()=>{toast('No pudimos cargar el carrito. Puedes seguir viendo las fichas y recargar.');$('#count').textContent='–';if($('#order-list'))$('#order-list').textContent='No pudimos cargar el catálogo. Recarga para ver el pedido.'});
})();
